function connectives(p, q) {
  if (typeof p !== "boolean" || typeof q !== "boolean") throw new TypeError("Boolean inputs required");
  return {and: p && q, or: p || q, xor: p !== q, implies: !p || q, iff: p === q};
}
function bitwise(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || !/^[01]+$/.test(a) || !/^[01]+$/.test(b) || a.length !== b.length) throw new TypeError("Equal nonempty bit strings required");
  const result = {and: "", or: "", xor: ""};
  for (let i = 0; i < a.length; i++) {
    const row = connectives(a[i] === "1", b[i] === "1");
    for (const key of ["and", "or", "xor"]) result[key] += row[key] ? "1" : "0";
  }
  return result;
}
